package br.com.rocardan.androws;

import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.provider.Settings;
import android.view.*;
import android.view.animation.*;
import android.widget.*;
import android.text.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
  private static final int[] PALETTE={0xff0078d7,0xff00a4ef,0xff00aba9,0xff00a300,0xff60a917,0xffa4c400,0xfff0a30a,0xfffa6800,0xffe51400,0xffe671b8,0xfff472d0,0xffa200ff,0xff643ebf,0xff1ba1e2,0xff647687,0xff76608a,0xff6d8764,0xff825a2c,0xffa0522d,0xff303030};
  private SharedPreferences prefs;
  private PackageManager pm;
  private final ArrayList<ResolveInfo> apps=new ArrayList<>();
  private final ArrayList<String> pinned=new ArrayList<>();
  private LinearLayout root, body;
  private int accent;
  private boolean dark, modern, editMode;
  private String screen="home";
  private final Handler handler=new Handler(Looper.getMainLooper());
  private TextView liveClock, liveDate;
  private final Runnable clockTick=new Runnable(){public void run(){if(liveClock!=null)liveClock.setText(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()));if(liveDate!=null)liveDate.setText(new SimpleDateFormat("EEEE, d MMMM",new Locale("pt","BR")).format(new Date()));handler.postDelayed(this,30000);}};
  private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
  private int foreground(){return dark?Color.WHITE:0xff111111;}
  private int background(){return dark?0xff080808:0xfff7f7f7;}
  private GradientDrawable block(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(modern?0:2));return g;}
  private TextView text(String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(foreground());t.setTypeface(Typeface.create("sans-serif-light",bold?Typeface.BOLD:Typeface.NORMAL));return t;}
  @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("androws",MODE_PRIVATE);pm=getPackageManager();accent=prefs.getInt("accent",PALETTE[0]);dark=prefs.getBoolean("dark",true);modern=prefs.getBoolean("modern",false);loadApps();loadPins();getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);handler.post(clockTick);showHome();}
  @Override protected void onDestroy(){handler.removeCallbacks(clockTick);super.onDestroy();}
  @Override protected void onResume(){super.onResume();loadApps();}
  private void loadApps(){Intent query=new Intent(Intent.ACTION_MAIN);query.addCategory(Intent.CATEGORY_LAUNCHER);apps.clear();apps.addAll(pm.queryIntentActivities(query,0));Collections.sort(apps,(a,b)->a.loadLabel(pm).toString().compareToIgnoreCase(b.loadLabel(pm).toString()));}
  private ResolveInfo find(String key){for(ResolveInfo a:apps)if(key.equals(a.activityInfo.packageName+"/"+a.activityInfo.name))return a;return null;}
  private String key(ResolveInfo a){return a.activityInfo.packageName+"/"+a.activityInfo.name;}
  private void loadPins(){pinned.clear();String saved=prefs.getString("pins_v11",null);if(saved!=null){for(String s:saved.split("\\|"))if(!s.isEmpty()&&find(s)!=null&&!pinned.contains(s))pinned.add(s);return;}String old=prefs.getString("pins","");for(String pkg:old.split("\\|")){for(ResolveInfo a:apps)if(a.activityInfo.packageName.equals(pkg)){if(!pinned.contains(key(a)))pinned.add(key(a));break;}}if(pinned.isEmpty()){for(ResolveInfo a:apps){if(pinned.size()==8)break;pinned.add(key(a));}}savePins();}
  private void savePins(){prefs.edit().putString("pins_v11",TextUtils.join("|",pinned)).apply();}
  private void page(String name){screen=name;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(background());setContentView(root);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);root.addView(body,new LinearLayout.LayoutParams(-1,-1));}
  private void header(String title,String action,Runnable callback){LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(18),dp(18),dp(16),dp(14));TextView name=text(title,35,false);bar.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView button=text(action,26,false);button.setTextColor(accent);button.setPadding(dp(12),0,dp(8),0);bar.addView(button);button.setOnClickListener(v->callback.run());body.addView(bar);}
  private void animate(View v,int index){v.setAlpha(0);v.setTranslationY(dp(25));v.animate().alpha(1).translationY(0).setDuration(320).setStartDelay(Math.min(index*45,400)).setInterpolator(new DecelerateInterpolator()).start();}
  private void showHome(){page("home");header(editMode?"editar início":"início","→",()->{editMode=false;showApps("");});ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout stack=new LinearLayout(this);stack.setOrientation(1);stack.setPadding(dp(12),0,dp(12),dp(28));scroll.addView(stack);
    LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);stack.addView(top);TextView brand=text("ANDROWS",12,true);brand.setLetterSpacing(.22f);brand.setTextColor(accent);top.addView(brand,new LinearLayout.LayoutParams(0,dp(44),1));brand.setGravity(Gravity.CENTER_VERTICAL);TextView gear=text("⚙",26,false);gear.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);top.addView(gear,new LinearLayout.LayoutParams(dp(60),dp(44)));gear.setOnClickListener(v->showSettings());
    int width=getResources().getDisplayMetrics().widthPixels-dp(30);int unit=(width-dp(9))/4;int index=0;int i=0;
    while(i<pinned.size()){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.TOP);stack.addView(row);int used=0;while(i<pinned.size()&&used<4){String id=pinned.get(i);ResolveInfo app=find(id);if(app==null){i++;continue;}int span=Math.max(1,Math.min(4,prefs.getInt("span_"+id,2)));if(span>4-used){if(used>0)break;span=4;}final int currentSpan=span;LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(7),dp(7),dp(7),dp(7));tile.setBackground(block(accent));int tileWidth=unit*span+dp(3)*(span-1);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(tileWidth,unit*(span==4?2:span)+dp(3)*(span==4?1:span-1));params.setMargins(dp(2),dp(2),dp(2),dp(2));row.addView(tile,params);ImageView icon=new ImageView(this);icon.setImageDrawable(app.loadIcon(pm));tile.addView(icon,new LinearLayout.LayoutParams(dp(span==1?32:49),dp(span==1?32:49)));TextView label=text(app.loadLabel(pm).toString(),span==1?11:15,false);label.setTextColor(Color.WHITE);label.setGravity(Gravity.CENTER);label.setMaxLines(2);label.setPadding(0,dp(8),0,0);tile.addView(label);if(editMode){TextView marker=text("✎",15,true);marker.setTextColor(Color.WHITE);tile.addView(marker);}tile.setOnClickListener(v->{if(editMode)tileMenu(id);else launch(id,tile);});tile.setOnLongClickListener(v->{editMode=true;tileMenu(id);return true;});animate(tile,index++);used+=currentSpan;i++;}if(used==0)break;}
    TextView instructions=text(editMode?"Toque em um bloco para editar.":"Segure um bloco para editar • Deslize para os aplicativos →",13,false);instructions.setTextColor(dark?0xffaaaaaa:0xff555555);instructions.setPadding(dp(5),dp(22),0,dp(16));stack.addView(instructions);if(editMode){TextView done=text("✓  concluir edição",20,false);done.setTextColor(accent);done.setPadding(dp(10),dp(14),0,dp(14));stack.addView(done);done.setOnClickListener(v->{editMode=false;showHome();});}
    scroll.setOnTouchListener(new View.OnTouchListener(){float x,y;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();}if(e.getAction()==MotionEvent.ACTION_UP&&x-e.getX()>dp(110)&&Math.abs(y-e.getY())<dp(85)){showApps("");return true;}return false;}});
  }
  private void launch(String id,View source){ResolveInfo a=find(id);if(a==null){Toast.makeText(this,"Aplicativo indisponível",Toast.LENGTH_SHORT).show();return;}source.animate().scaleX(.87f).scaleY(.87f).alpha(.6f).setDuration(110).withEndAction(()->{try{Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);intent.setClassName(a.activityInfo.packageName,a.activityInfo.name);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(intent);overridePendingTransition(android.R.anim.fade_in,android.R.anim.fade_out);}catch(Exception ex){Toast.makeText(this,"Não foi possível abrir",Toast.LENGTH_SHORT).show();}source.setScaleX(1);source.setScaleY(1);source.setAlpha(1);}).start();}
  private void tileMenu(String id){String[] options={"Abrir","Mover para cima","Mover para baixo","Pequeno (1×1)","Médio (2×2)","Largo (4×2)","Desafixar"};new AlertDialog.Builder(this).setTitle("Personalizar bloco").setItems(options,(dialog,choice)->{int pos=pinned.indexOf(id);if(choice==0){ResolveInfo a=find(id);if(a!=null)launch(id,new View(this));return;}if(choice==1&&pos>0)Collections.swap(pinned,pos,pos-1);if(choice==2&&pos>=0&&pos<pinned.size()-1)Collections.swap(pinned,pos,pos+1);if(choice>=3&&choice<=5)prefs.edit().putInt("span_"+id,choice==3?1:choice==4?2:4).apply();if(choice==6)pinned.remove(id);savePins();showHome();}).show();}
  private void showApps(String filter){page("apps");header("aplicativos","⌂",()->{editMode=false;showHome();});EditText search=new EditText(this);search.setSingleLine();search.setHint("Pesquisar");search.setTextColor(foreground());search.setHintTextColor(0xff888888);search.setPadding(dp(20),dp(8),dp(20),dp(12));body.addView(search);ScrollView scroll=new ScrollView(this);body.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);search.setText(filter);populate(list,filter);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){populate(list,s.toString());}public void afterTextChanged(Editable e){}});}
  private void populate(LinearLayout list,String query){list.removeAllViews();String previous="";int index=0;for(ResolveInfo a:apps){String name=a.loadLabel(pm).toString();if(!name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;String letter=name.isEmpty()?"#":name.substring(0,1).toUpperCase(Locale.ROOT);if(query.isEmpty()&&!letter.equals(previous)){TextView l=text(letter,29,false);l.setTextColor(accent);l.setPadding(dp(20),dp(10),0,dp(6));list.addView(l);previous=letter;}LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(20),dp(10),dp(12),dp(10));ImageView icon=new ImageView(this);icon.setImageDrawable(a.loadIcon(pm));row.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView label=text(name,20,false);label.setPadding(dp(16),0,0,0);row.addView(label);list.addView(row);String id=key(a);row.setOnClickListener(v->launch(id,row));row.setOnLongClickListener(v->{new AlertDialog.Builder(this).setItems(new String[]{pinned.contains(id)?"Desafixar":"Fixar na tela inicial"},(d,n)->{if(pinned.contains(id))pinned.remove(id);else pinned.add(id);savePins();Toast.makeText(this,"Tela inicial atualizada",Toast.LENGTH_SHORT).show();}).show();return true;});if(index++<15)animate(row,index);}}
  private void setting(LinearLayout list,String title,String subtitle,Runnable action){LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setPadding(dp(12),dp(16),dp(10),dp(16));TextView name=text(title,22,false);item.addView(name);TextView sub=text(subtitle,14,false);sub.setTextColor(0xff888888);item.addView(sub);list.addView(item);item.setOnClickListener(v->action.run());View line=new View(this);line.setBackgroundColor(dark?0xff303030:0xffdddddd);list.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
  private void showSettings(){page("settings");header("configurações","⌂",()->showHome());ScrollView scroll=new ScrollView(this);body.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(14),0,dp(14),dp(25));scroll.addView(list);setting(list,"Estilo Metro",modern?"Windows 10 Mobile":"Windows Phone 8.1",()->new AlertDialog.Builder(this).setItems(new String[]{"Windows Phone 8.1","Windows 10 Mobile"},(d,n)->{modern=n==1;prefs.edit().putBoolean("modern",modern).apply();showSettings();}).show());setting(list,"Tema",dark?"Escuro":"Claro",()->{dark=!dark;prefs.edit().putBoolean("dark",dark).apply();showSettings();});setting(list,"Cor de destaque","20 opções",this::chooseColor);setting(list,"Launcher padrão","Selecionar Androws como tela inicial",()->startActivity(new Intent(Settings.ACTION_HOME_SETTINGS)));setting(list,"Notificações","Abrir permissões de acesso às notificações",()->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));setting(list,"Sobre","ANDROWS 1.1 • ROCARDAN SYSTEMS",()->new AlertDialog.Builder(this).setTitle("ANDROWS 1.1").setMessage("Metro Experience\nROCARDAN SYSTEMS\nAndroid 15+").setPositiveButton("OK",null).show());}
  private void chooseColor(){ScrollView scroll=new ScrollView(this);LinearLayout all=new LinearLayout(this);all.setOrientation(1);scroll.addView(all);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Cores Metro").setView(scroll).setNegativeButton("Fechar",null).create();for(int r=0;r<5;r++){LinearLayout row=new LinearLayout(this);all.addView(row);for(int c=0;c<4;c++){int color=PALETTE[r*4+c];TextView swatch=text("■",45,true);swatch.setTextColor(color);swatch.setGravity(Gravity.CENTER);row.addView(swatch,new LinearLayout.LayoutParams(0,dp(70),1));swatch.setOnClickListener(v->{accent=color;prefs.edit().putInt("accent",color).apply();dialog.dismiss();showSettings();});}}dialog.show();}
  @Override public void onBackPressed(){if(editMode){editMode=false;showHome();}else if(!screen.equals("home"))showHome();else super.onBackPressed();}
}
